import re,os,subprocess
root='.'
files=subprocess.check_output(['git','-C','/Users/kristinarash/.claude/skills','ls-files','impeccable']).decode().split()
files=[f[len('impeccable/'):] for f in files]
texts={f:open(f,errors='ignore').read() for f in files if f.endswith(('.md','.json','.js')) and 'data/' not in f}
# links
missing=[];refd=set()
for f,t in texts.items():
    for m in re.findall(r'\]\(([^)#\s]+)',t)+re.findall(r'`((?:reference|scripts)/[\w./-]+)`',t):
        if m.startswith('http'):continue
        p=os.path.normpath(os.path.join(os.path.dirname(f),m))
        p2=os.path.normpath(m)
        if os.path.exists(p): refd.add(p)
        elif os.path.exists(p2): refd.add(p2)
        else: missing.append((f,m))
print('missing',missing[:30])
allmd=[f for f in files if f.startswith('reference/')]
# basename mention
for f in allmd:
    b=os.path.basename(f)
    if f not in refd and not any(b in t for g,t in texts.items() if g!=f):
        print('unref',f)
E

